<template><Card class="s45-manager"><template v-if="!$route.params.id"><h2>售后管理</h2><p class="intro">按原申请查询商品、退回、争议与资金进度，平台业务结论不直接改变资金终态。</p><RecordList endpoint="/aftersales" :states="states" :columns="columns" @open="open"/></template><template v-else><Button @click="back">返回售后列表</Button><Button :loading="loading" @click="load">刷新当前事实</Button><Alert v-if="error" type="error" show-icon>{{error}}</Alert><OperationRecovery :name="'resolve:'+$route.params.id" :revision="revision" @recovered="load"/><template v-if="detail"><h2>{{detail.storeName}} · {{label(detail.state)}}</h2><section class="detail-section"><h3>原申请与业务层级</h3><dl class="facts"><div v-for="row in facts" :key="row[0]" class="fact"><dt>{{row[0]}}</dt><dd>{{row[1]}}</dd></div></dl><p style="white-space:pre-wrap">{{detail.reason}}</p></section><section class="detail-section"><h3>居民与商户证据</h3><Evidence :ids="detail.files||[]"/></section><section v-if="detail.returnGuide" class="detail-section"><h3>已确认退回方式快照</h3><p>{{detail.returnGuide.method==='LOGISTICS'?'物流退回':'线下交回'}} · {{detail.returnGuide.contact}} {{detail.returnGuide.phone}}</p><p>{{detail.returnGuide.address}}</p><p>{{detail.returnGuide.instructions}}</p><template v-if="detail.returnInfo"><h4>居民已提交退回</h4><p>{{detail.returnInfo.company}} {{detail.returnInfo.number}}</p><p>{{detail.returnInfo.note}}</p></template><p class="meta">提交物流或线下说明不等于已收货；平台不能跳过实际收货条件直接退款。</p></section><section class="detail-section"><h3>退款与费用进度</h3><p>商品申请 {{money(detail.amountCent)}} · 已成功 {{money(detail.refundedCent)}} · {{label(detail.fundingState)}}</p><p v-for="fee in detail.feeObligations||[]" :key="fee.id">独立费用义务 {{money(fee.amountCent)}} · {{label(fee.state)}} · {{date(fee.succeededAt)}}</p><p class="meta">审核同意、退回和渠道受理均不等于最终退款成功；费用退款不追加到商品申请金额。</p></section><Form v-if="detail.actions.includes('resolve')" label-position="top" class="detail-section"><h3>争议处理</h3><FormItem label="业务结论 *"><Select v-model="decision"><Option value="APPROVE">同意原范围</Option><Option value="MAINTAIN">维持原处理结论</Option><Option value="NEED_EVIDENCE">要求补充证据</Option></Select></FormItem><FormItem label="结论原因 *"><Input v-model="reason" type="textarea" :maxlength="500" :disabled="busy" placeholder="填写可向当事人解释的业务依据"/></FormItem><template v-if="decision==='APPROVE'&&detail.state==='REJECTED'&&detail.type==='RETURN_REFUND'"><h4>确认退回安排</h4><FormItem label="退回方式"><Select v-model="guide.method"><Option value="LOGISTICS">物流退回</Option><Option value="OFFLINE">线下交回</Option></Select></FormItem><FormItem label="联系人"><Input v-model="guide.contact" :maxlength="80"/></FormItem><FormItem label="电话"><Input v-model="guide.phone" :maxlength="40"/></FormItem><FormItem label="地址 / 交回地点"><Input v-model="guide.address" :maxlength="500"/></FormItem><FormItem label="交回说明"><Input v-model="guide.instructions" :maxlength="500"/></FormItem></template><FormItem v-if="decision==='APPROVE'" label="争议履约费（元，选填）"><Input v-model="fee" maxlength="18" placeholder="留空则不建立费用义务"/><p class="meta">只在原费用额度和业务条件内形成独立义务，服务端重新核验。</p></FormItem><Button type="primary" :loading="busy" :disabled="pending||!decision" @click="resolve">提交业务结论</Button></Form><h3>完整处理历史</h3><div class="history" v-for="(row,index) in detail.timeline" :key="index"><p>{{label(row.action)}} · {{row.reason||'已记录业务处理'}}</p><p class="meta">{{date(row.at)}}</p></div></template></template></Card></template>
<script>
import RecordList from './components/RecordList.vue';import OperationRecovery from './components/OperationRecovery.vue';import Evidence from './components/Evidence.vue';import {s45Read,s45Commands} from '@/api/stage45';import {managerSession} from '@/libs/manager-session';import {label,money,date} from './presentation.cjs';
export default{components:{RecordList,OperationRecovery,Evidence},data(){return{detail:null,loading:false,busy:false,error:'',ticket:0,revision:0,decision:'',reason:'',fee:'',guide:{method:'LOGISTICS',contact:'',phone:'',address:'',instructions:''},states:['APPLY','WAIT_RETURN','WAIT_RECEIVE','WAIT_FUNDS','DISPUTE','COMPLETE','REJECTED','CANCELLED'],columns:[{title:'售后 / 订单',minWidth:240,render:(h,{row})=>h('div',[h('p',row.sn),h('p',row.orderSn)])},{title:'店铺 / 商品',minWidth:240,render:(h,{row})=>h('div',[h('p',row.storeName),h('p',row.goodsName)])},{title:'类型 / 数量',minWidth:140,render:(h,{row})=>h('span',label(row.type)+' / '+row.quantity+' 件')},{title:'申请商品款',minWidth:140,render:(h,{row})=>h('span',money(row.amountCent))},{title:'售后状态',minWidth:140,render:(h,{row})=>h('span',label(row.state))},{title:'资金状态',minWidth:140,render:(h,{row})=>h('span',label(row.fundingState))},{title:'申请时间',minWidth:190,render:(h,{row})=>h('span',date(row.createdAt))}]}},computed:{pending(){this.revision;return s45Commands.pending('resolve:'+this.$route.params.id)},facts(){const d=this.detail;return [['售后单号',d.sn],['原合单号',d.tradeSn],['原 Store Order',d.orderSn],['原商品项',d.goodsName],['申请类型',label(d.type)],['申请数量',d.quantity+' 件'],['原申请商品款',money(d.amountCent)],['当前争议',label(d.dispute)],['申请时间',date(d.createdAt)],['商品退款成功时间',date(d.refundedAt)]]}},watch:{'$route.params.id':{handler(){this.ticket++;this.detail=null;this.decision='';this.reason='';this.fee='';if(this.$route.params.id)this.load()},immediate:true}},beforeDestroy(){this.ticket++;this.detail=null},methods:{label,money,date,open(row){this.$router.push({path:'/s45/aftersales/'+row.id,query:this.$route.query})},back(){this.$router.push({path:'/s45/aftersales',query:this.$route.query})},async load(){if(!this.$route.params.id)return;const ticket=++this.ticket,owner=managerSession.snapshot();this.loading=true;this.error='';try{const v=await s45Read('/aftersales/'+this.$route.params.id);if(ticket===this.ticket&&managerSession.sameSession(owner)){this.detail=v;if(v.returnGuide)this.guide={...v.returnGuide}}}catch(e){if(ticket===this.ticket){this.detail=null;this.error=e.message}}finally{if(ticket===this.ticket)this.loading=false}},resolve(){if(!this.detail||this.pending||this.busy)return;if(!this.decision||this.reason.trim().length<2){this.error='请选择业务结论并填写至少2字的原因。';return}const body={expectedVersion:this.detail.version,decision:this.decision,reason:this.reason.trim()};if(this.fee.trim()){if(!/^(?:0|[1-9][0-9]*)(?:\.[0-9]{1,2})?$/.test(this.fee)){this.error='请填写有效的正数费用金额。';return}const [yuan,cent='']=this.fee.split('.');const amount=Number(yuan)*100+Number(cent.padEnd(2,'0'));if(!Number.isSafeInteger(amount)||amount<=0){this.error='费用金额须为有效正整数分。';return}body.feeCent=amount}if(this.decision==='APPROVE'&&this.detail.state==='REJECTED'&&this.detail.type==='RETURN_REFUND')body.returnGuide={...this.guide};this.$Modal.confirm({title:'提交争议业务结论',content:'按原商品范围作结论。退货仍需实际收货，资金结果由原义务继续处理。',onOk:async()=>{this.busy=true;this.error='';try{await s45Commands.run('resolve:'+this.detail.id,'/aftersales/'+this.detail.id+'/resolve',body);this.decision='';this.reason='';this.fee='';this.load()}catch(e){this.error=e.message}finally{this.revision++;this.busy=false}}})}}};
</script><style lang="scss">@import './stage45.scss';</style>
